    public static function get($name = 'default', $extraClasses = '') {
        $key = strtolower(trim($name));
        $svg = self::$icons[$key] ?? self::$icons['default'];
        if ($extraClasses) {
            $svg = str_replace('class="', 'class="' . htmlspecialchars($extraClasses) . ' ', $svg);
        }
        return $svg;
    }

    public static function render($iconString, $extraClasses = '') {
        // If string contains SVG tag, return it
        if (strpos($iconString, '<svg') !== false) {
            return $iconString;
        }
        // Map common emoji/words to SVG keys
        $map = [
            '✏️' => 'text', '📄' => 'pdf', '🖼️' => 'image', '💻' => 'code',
            '⚡' => 'calc', '🔄' => 'convert', '🎲' => 'random', '🔗' => 'link',
            '💼' => 'business', '📸' => 'instagram', '🧾' => 'invoice'
        ];

        $key = $map[$iconString] ?? $iconString;
        return self::get($key, $extraClasses);
    }
}
